using Microsoft.Data.Sqlite;
using ChineseShiftScheduler.Models;
namespace ChineseShiftScheduler.Services;
public sealed class ScheduleStore {
 private readonly string _cs;
 public ScheduleStore() { var dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ChineseShiftScheduler"); Directory.CreateDirectory(dir); _cs=new SqliteConnectionStringBuilder{DataSource=Path.Combine(dir,"scheduler.db")}.ToString(); using var c=Open(); using var q=c.CreateCommand(); q.CommandText="CREATE TABLE IF NOT EXISTS Employees(Id INTEGER PRIMARY KEY AUTOINCREMENT,Name TEXT NOT NULL,Position TEXT NOT NULL,CycleStartDate TEXT NOT NULL); CREATE TABLE IF NOT EXISTS Overrides(EmployeeId INTEGER NOT NULL,WorkDate TEXT NOT NULL,ShiftName TEXT NOT NULL,PRIMARY KEY(EmployeeId,WorkDate));"; q.ExecuteNonQuery(); Seed(); }
 private SqliteConnection Open(){var c=new SqliteConnection(_cs);c.Open();return c;}
 private void Seed(){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT COUNT(*) FROM Employees";if(Convert.ToInt32(q.ExecuteScalar())>0)return;q.CommandText="INSERT INTO Employees(Name,Position,CycleStartDate) VALUES('示例员工','护理人员','"+DateTime.Today.ToString("yyyy-MM-dd")+"')";q.ExecuteNonQuery();}
 public List<Employee> Employees(){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT Id,Name,Position,CycleStartDate FROM Employees ORDER BY Id";using var r=q.ExecuteReader();var a=new List<Employee>();while(r.Read())a.Add(new Employee{Id=r.GetInt32(0),Name=r.GetString(1),Position=r.GetString(2),CycleStartDate=DateTime.Parse(r.GetString(3))});return a;}
 public void Save(Employee e){using var c=Open();using var q=c.CreateCommand();q.CommandText=e.Id==0?"INSERT INTO Employees(Name,Position,CycleStartDate) VALUES($n,$p,$d)":"UPDATE Employees SET Name=$n,Position=$p,CycleStartDate=$d WHERE Id=$id";q.Parameters.AddWithValue("$n",e.Name);q.Parameters.AddWithValue("$p",e.Position);q.Parameters.AddWithValue("$d",e.CycleStartDate.ToString("yyyy-MM-dd"));if(e.Id!=0)q.Parameters.AddWithValue("$id",e.Id);q.ExecuteNonQuery();}
 public void Delete(int id){using var c=Open();using var q=c.CreateCommand();q.CommandText="DELETE FROM Employees WHERE Id=$id; DELETE FROM Overrides WHERE EmployeeId=$id";q.Parameters.AddWithValue("$id",id);q.ExecuteNonQuery();}
 public string? Override(int id,DateTime d){using var c=Open();using var q=c.CreateCommand();q.CommandText="SELECT ShiftName FROM Overrides WHERE EmployeeId=$i AND WorkDate=$d";q.Parameters.AddWithValue("$i",id);q.Parameters.AddWithValue("$d",d.ToString("yyyy-MM-dd"));return q.ExecuteScalar() as string;}
 public void SetOverride(int id,DateTime d,string s){using var c=Open();using var q=c.CreateCommand();q.CommandText="INSERT INTO Overrides VALUES($i,$d,$s) ON CONFLICT(EmployeeId,WorkDate) DO UPDATE SET ShiftName=excluded.ShiftName";q.Parameters.AddWithValue("$i",id);q.Parameters.AddWithValue("$d",d.ToString("yyyy-MM-dd"));q.Parameters.AddWithValue("$s",s);q.ExecuteNonQuery();}
 public void ClearOverride(int id,DateTime d){using var c=Open();using var q=c.CreateCommand();q.CommandText="DELETE FROM Overrides WHERE EmployeeId=$i AND WorkDate=$d";q.Parameters.AddWithValue("$i",id);q.Parameters.AddWithValue("$d",d.ToString("yyyy-MM-dd"));q.ExecuteNonQuery();}
 public static string Cycle(DateTime date,DateTime start){int n=(int)(date.Date-start.Date).TotalDays;return ((n%4)+4)%4 switch {0=>"白班",1=>"夜班",_=>"休息"};}
}